INSERT INTO `tor` (`torID`, `documentID`, `kode_unit_eselon1`, `nama_unit_eselon1`, `kode_unit_eselon2`, `nama_unit_eselon2`, `kode_satker`, `nama_satker`, `kode_program`, `nama_program`, `kode_kegiatan`, `nama_kegiatan`, `kode_kro`, `nama_kro`, `kode_ro`, `nama_ro`, `rincian_output`, `volume_ro`, `satuan_ro`, `gambaran_umum`, `metode_pelaksanaan`, `kurun_waktu_pencapaian_keluaran`, `total_biaya`, `dasar_hukum`, `penerima_manfaat`, `tahapan_pelaksanaan`, `jadwal_pelaksanaan`, `created_at`, `updated_at`) VALUES
('tor00000002', 'doc00005', '09', 'Direktorat Jenderal Perlindungan Konsumen dan Tertib Niaga', '09.21', 'Direktorat Tertib Niaga', '403444', 'DIREKTORAT TERTIB NIAGA', 'WA', 'Program Dukungan Manajemen', '3977', 'Dukungan Manajemen dan Dukungan Teknis Lainnya Ditjen Perlindungan Konsumen dan Tertib Niaga', 'EBA', 'Layanan Dukungan Manajemen Internal', '994', 'Layanan Perkantoran', 'Layanan Perkantoran', 1.00, 'Layanan', 'Layanan perkantoran merupakan bagian dari dukungan manajemen dan ketatausahaan pengembangan standardisasi bidang perdagangan yang diselenggarakan secara konsisten dan kontinual dalam 12 bulan berjalan secara efektif. Tujuannya adalah untuk memberikan pelayanan keperluan sehari-hari dan operasional Satuan Kerja Direktorat Tertib Niaga serta dukungan manajemen yang meliputi pembinaan kepegawaian, penyusunan rencana, monitoring, dan evaluasi sehingga terwujud pelayanan prima guna mencapai tujuan organisasi secara efektif dan efisien.', NULL, '12 (dua belas) Bulan', 461280000.00, '[\"Undang-undang RI Nomor 17 tahun 2003 tentang Keuangan Negara\", \"Undang-Undang Republik Indonesia No. 1 Tahun 2004 tentang Perbendaharaan Negara\", \"Undang-Undang Nomor 25 Tahun 2004 tentang Sistem Perencanaan Pembangunan Nasional\", \"Undang-Undang Republik Indonesia Nomor 5 Tahun 2014 tentang Aparatur Sipil Negara\", \"Undang-Undang Republik Indonesia No. 7 Tahun 2014 tentang Perdagangan\", \"Peraturan Pemerintah Nomor 27 Tahun 2014 tentang Pengelolaan Barang Milik Negara/Daerah\", \"Peraturan Menteri Perdagangan Nomor 61 tahun 2021 tentang Perubahan atas Peraturan Menteri Perdagangan Nomor 81 Tahun 2020 tentang Organisasi dan Tata Kerja Unit Pelaksana Teknis Kementerian Perdagangan\", \"Peraturan Menteri Perdagangan Nomor 6 tahun 2025 tentang Organisasi dan Tata Kerja Kementerian Perdagangan\"]', '[\"Pegawai di lingkungan Direktorat Tertib Niaga melalui penyediaan kebutuhan operasional pegawai dalam menunjang pelaksanaan tugas dan fungsi\", \"Pegawai Direktorat Tertib Niaga dalam menunjang pelaksanaan tugas dan fungsi\", \"Stakeholder terkait melalui penyediaan layanan perkantoran di bidang tertib niaga\"]', '[\"Operasional Kantor\", \"Operasional Pimpinan\", \"Honorarium Operasional Satuan Kerja Direktorat Tertib Niaga\", \"Langganan Daya dan Jasa\", \"Sewa Kendaraan Dinas\", \"Pemeliharaan dan Operasional Kendaraan\", \"Pemeliharaan dan Operasional Peralatan dan Mesin\"]', '[{\"nama_kegiatan\": \"Operasional dan pemeliharaan perkantoran\", \"waktu_pelaksanaan\": \"Bulan 1-12\"}]', '2026-08-20 02:16:03', '2026-08-20 02:16:03'),
('tor00000003', 'doc00006', '09', 'Direktorat Jenderal Perlindungan Konsumen dan Tertib Niaga', '09.20', 'Direktorat Standardisasi dan Pengendalian Mutu', '647931', 'BALAI KALIBRASI', 'WA', 'Program Dukungan Manajemen', '3977', 'Dukungan Manajemen dan Dukungan Teknis Lainnya Ditjen Perlindungan Konsumen dan Tertib Niaga', 'EBA', 'Layanan Dukungan Manajemen Internal', '994', 'Layanan Perkantoran', 'Layanan Perkantoran', 1.00, 'Layanan', 'Dalam rangka menunjang pelaksanaan kegiatan Balai Kalibrasi terutama untuk memenuhi undangan kegiatan dan melakukan kegiatan operasional dalam kota, maka Satker Balai Kalibrasi menyiapkan keperluan transport yang bersifat dalam kota. Balai Kalibrasi sebagai UAKPB wajib bertanggung jawab terhadap BMN sesuai PP Nomor 28 Tahun 2020. Pemeliharaan peralatan, mesin, dan kendaraan bermotor dilakukan secara terus menerus untuk menunjang kelancaran pelaksanaan tugas pelayanan kepada masyarakat dan dunia usaha. Selain itu, diperlukan dukungan langganan daya dan jasa, khususnya telepon, agar penyelesaian pekerjaan dapat terlaksana dengan lancar dan tepat waktu.', 'Operasional dan Pemeliharaan Perkantoran', 'Setiap bulan pada tahun 2027', 151800000.00, '[\"Peraturan Menteri Perdagangan Nomor 28 Tahun 2025 Tentang Organisasi dan Tata Kerja Unit Pelaksana Teknis Kementerian Perdagangan.\", \"Peraturan Menteri Keuangan Republik Indonesia Nomor 32 Tahun 2025 tentang Standar Biaya Masukan Tahun Anggaran 2026.\", \"Peraturan Menteri Keuangan Nomor 107 Tahun 2024 tentang Perencanaan Anggaran, Pelaksanaan Anggaran, serta Akuntansi dan Pelaporan Keuangan.\", \"Peraturan Pemerintah Republik Indonesia Nomor 28 Tahun 2020 tentang Pengelolaan Barang Milik Negara/Daerah\", \"SNI ISO/IEC 17025:2017 tentang Persyaratan Umum Kompetensi Laboratorium Pengujian dan Kalibrasi.\", \"SNI ISO 9001:2015 tentang Sistem Manajemen Mutu.\", \"SNI ISO/IEC 17043:2023 tentang Persyaratan Umum Kompetensi Penyelenggara Uji Profisiensi.\"]', '[\"Pegawai dan Balai Kalibrasi\"]', '[\"Penjadwalan dan pembuatan surat tugas\", \"Distribusi surat tugas ke pegawai\", \"Pembayaran uang transport dalam kota\", \"Persiapan pelaksanaan pemeliharaan dan perbaikan peralatan meliputi inventarisasi peralatan, pengecekan, penunjukan penyedia, dan penjadwalan\", \"Pelaksanaan kegiatan pemeliharaan\", \"Pelaporan pemeliharaan\", \"Persiapan pelaksanaan pengadaan keperluan perkantoran meliputi inventarisasi kebutuhan, pengecekan, penunjukan penyedia, dan penjadwalan\", \"Pelaksanaan kegiatan pengadaan\", \"Pelaporan pengadaan\", \"Pembayaran rekening telepon setiap bulan\", \"Pelaporan hasil pembayaran\"]', '[]', '2026-08-20 02:21:54', '2026-08-20 02:21:54'),
('tor00000004', 'doc00007', '09', 'Direktorat Jenderal Perlindungan Konsumen dan Tertib Niaga', '09.20', 'Direktorat Standardisasi dan Pengendalian Mutu', '647931', 'BALAI KALIBRASI', 'EF', 'Program Perdagangan Dalam Negeri', '3734', 'Peningkatan Pelayanan Kalibrasi', 'CCH', 'OM Sarana Bidang Industri dan Perdagangan', '021', 'Ruang Lingkup Pelayanan Kalibrasi Yang Dipelihara dan Dikembangkan', 'Ruang Lingkup Pelayanan Kalibrasi Yang Dipelihara dan Dikembangkan', 2.00, 'Unit', NULL, NULL, NULL, 1146883000.00, '[]', '[]', '[]', '[]', '2026-08-20 04:42:15', '2026-08-20 04:42:15');
